import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Theme Settings',
  description: 'Display user theme and language preferences'
};

export default function RootLayout({
  children
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

input.content:
import { cookies, headers } from 'next/headers';

export default async function ThemePreferences() {
  const cookieStore = await cookies();
  const headersList = await headers();

  const theme = cookieStore.get('theme')?.value ?? 'light';
  const acceptLanguage = headersList.get('accept-language') ?? 'unknown';
  // Take the first language tag (e.g. "en-US" from "en-US,en;q=0.9,fr;q=0.8")
  const preferredLanguage = acceptLanguage.split(',')[0].trim();

  return (
    <section>
      <h2>User Preferences</h2>
      <p>
        <strong>Theme:</strong> {theme}
      </p>
      <p>
        <strong>Preferred language:</strong> {preferredLanguage}
      </p>
    </section>
  );
}

